func mixedAssertCommitOrderafter(
	tb testing.TB,
	m Mixed,
) {
	tb.Helper()
	ctx := tb.Context()
	err := m.Commit(ctx)
	if !errors.Is(err, orderafter.ErrNotReady) {
		tb.Errorf("Commit must report %v: got %v", orderafter.ErrNotReady, err)
	}
}

